.mapboxgl-ctrl button.mapboxgl-ctrl-level-button-selected:hover{background-color:#ccc}
/* gt-a11y-bridge (Tranche 0, group AX / WP-T0-10): temporary CSS shim over inline-styled React; remove rule by rule as source fixes land */
.gt-sr-only{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.gt-skip{position:fixed;left:8px;top:-120px;z-index:1000001;padding:10px 16px;background:#0a0a14;color:#f4f0e4;border:2px solid #fff;border-radius:6px;font:600 14px/1.2 system-ui,sans-serif;text-decoration:none}
.gt-skip:focus{top:8px}
:focus-visible{outline:2px solid #fff!important;outline-offset:2px!important;box-shadow:0 0 0 4px #000!important}
[style*=" color: rgb(68, 68, 68)"],[style^="color: rgb(68, 68, 68)"],[style*=" color: rgb(85, 85, 85)"],[style^="color: rgb(85, 85, 85)"]{color:#8f8fa3!important}
[style*=" color: rgb(102, 102, 102)"],[style^="color: rgb(102, 102, 102)"]{color:#9a9aab!important}
[style*=" color: rgb(119, 119, 119)"],[style^="color: rgb(119, 119, 119)"]{color:#a8a8b8!important}
[style*=" color: rgb(139, 105, 20)"],[style^="color: rgb(139, 105, 20)"]{color:#b8963c!important}
[style*=" color: rgb(58, 107, 196)"],[style^="color: rgb(58, 107, 196)"]{color:#7fa8ff!important}
[style*=" color: rgb(204, 68, 68)"],[style^="color: rgb(204, 68, 68)"],[style*=" color: rgb(196, 58, 58)"],[style^="color: rgb(196, 58, 58)"]{color:#f07a7a!important}
[style*=" color: rgb(109, 122, 138)"],[style^="color: rgb(109, 122, 138)"]{color:#9aa6b6!important}
[style*=" color: rgba(200, 168, 74, 0.45)"],[style^="color: rgba(200, 168, 74, 0.45)"]{color:rgba(200,168,74,.8)!important}
.gtbg-group-why,#gtbg-footer,#boot-splash .boot-caption{color:#9a9aab!important}
input::placeholder,textarea::placeholder{color:#9a9aab!important;opacity:1}
[data-gt-row]:focus-visible{outline-offset:-4px!important;box-shadow:none!important;background-color:rgba(200,168,74,.16)!important}
[style*="font-size: 7px"],[style*="font-size: 8px"],[style*="font-size: 9px"],[style*="font-size: 10px"],[style*="font-size: 11px"]{font-size:12px!important}
#root input[type=checkbox],#root input[type=radio]{width:24px;height:24px}
#root button,#extra-features button{min-width:24px;min-height:24px}
@media (pointer:coarse){#root button,#root a[href],#root select,#extra-features button,#extra-features a{min-width:44px;min-height:44px}#root .gtbg-tb-right button{min-width:24px}}
@media (max-width:1279px){.gtbg-tb-tick{display:none}}
@media (max-width:1199px){.gtbg-tb-right{gap:2px!important}.gtbg-tb-right button{padding-left:6px!important;padding-right:6px!important}}
@media (max-width:999px){.gtbg-tb-center{position:absolute!important;left:50%!important;transform:translateX(-50%)!important}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
@media (forced-colors:active){button,[role=button],input,select{border:1px solid ButtonText!important}:focus-visible{outline:2px solid Highlight!important;box-shadow:none!important}canvas{forced-color-adjust:none}}
